pub fn mpCollSqueezeHorizontal<'a>(
    ctx: &'a Ctx,
    coll: CollData<'a>,
    airborne: i32,
    left: f64,
    right: f64,
) {
    let mut coll = coll;
    let mut airborne = airborne;
    let mut left = left;
    let mut right = right;
    let mut half_width: f64 = fp::fmuls(
        0.5,
        (fp::fsubs(
            fp::fadds((coll).ecb().right().x(), fp::fsubs(right, left)),
            (coll).ecb().left().x(),
        )),
    );
    if !((coll).x34_flags().b6() != 0) {
        Handle::copy_from((coll).x64_ecb(), (coll).ecb());
    }
    (coll).x34_flags().set_b6((1_i32 as u8));
    (coll).cur_pos().set_x(fp::fsubs(
        (fp::fadds(right, (coll).ecb().right().x())),
        half_width,
    ));
    (coll).ecb().right().set_x(half_width);
    (coll).ecb().left().set_x(fp::fneg(half_width));
    (coll).desired_ecb().right().set_x((coll).ecb().right().x());
    (coll).desired_ecb().left().set_x((coll).ecb().left().x());
    (coll).x34_flags().set_b5((0_i32 as u8));
}

pub fn mpCollSqueezeVertical<'a>(
    ctx: &'a Ctx,
    coll: CollData<'a>,
    airborne: i32,
    top: f64,
    bottom: f64,
) {
    let mut coll = coll;
    let mut airborne = airborne;
    let mut top = top;
    let mut bottom = bottom;
    let mut height: f64 = fp::fsubs(
        fp::fadds((coll).ecb().top().y(), fp::fsubs(top, bottom)),
        (coll).ecb().bottom().y(),
    );
    let mut mid_y: f64 = 0.0;
    if !((coll).x34_flags().b6() != 0) {
        Handle::copy_from((coll).x64_ecb(), (coll).ecb());
    }
    (coll).x34_flags().set_b6((1_i32 as u8));
    if height < 3.0 {
        let mut old_height: f64 = fp::fsubs((coll).ecb().top().y(), (coll).ecb().bottom().y());
        let mut new_height: f64 = fp::fsubs(fp::fadds((coll).ecb().top().y(), top), bottom);
        (coll).ecb().top().set_y(
            (if (old_height) < (new_height) {
                (old_height)
            } else {
                (new_height)
            }),
        );
        (coll).ecb().bottom().set_y(0.0);
        (coll).cur_pos().set_y(bottom);
    } else if !(airborne != 0) {
        (coll).cur_pos().set_y(bottom);
        (coll)
            .ecb()
            .top()
            .set_y(fp::fadds(height, (coll).ecb().bottom().y()));
    } else {
        (coll)
            .cur_pos()
            .set_y(fp::fmuls(0.5, (fp::fadds(top, bottom))));
        (coll).ecb().top().set_y(fp::fmuls(
            0.5,
            (fp::fadds(
                height,
                fp::fadds((coll).ecb().top().y(), (coll).ecb().bottom().y()),
            )),
        ));
        (coll)
            .ecb()
            .bottom()
            .set_y(fp::fsubs((coll).ecb().top().y(), height));
    }
    mid_y = fp::fmuls(
        0.5,
        (fp::fadds((coll).ecb().top().y(), (coll).ecb().bottom().y())),
    );
    (coll).ecb().right().set_y(mid_y);
    (coll).ecb().left().set_y(mid_y);
    (coll).desired_ecb().top().set_y((coll).ecb().top().y());
    (coll)
        .desired_ecb()
        .bottom()
        .set_y((coll).ecb().bottom().y());
    (coll).desired_ecb().left().set_y((coll).ecb().left().y());
    (coll).desired_ecb().right().set_y((coll).ecb().right().y());
    (coll).x34_flags().set_b5((0_i32 as u8));
}

pub fn mpColl_8004CA6C<'a>(ctx: &'a Ctx, coll: CollData<'a>) -> f64 {
    let __frame = ctx.stack_frame(0x8);
    let mut coll = coll;
    let mut result: f64 = 1.0;
    if (coll).floor().index() != 1_i32.wrapping_neg() {
        result = fns::mpLib_800569EC(ctx, (coll).floor().flags());
    }
    return result;
}

pub fn mpCollGetSpeedCeiling<'a>(ctx: &'a Ctx, coll: CollData<'a>, speed: Vec<'a>) -> i32 {
    let __frame = ctx.stack_frame(0x20);
    let top: Vec<'a> = frame_at(ctx, &__frame, 0x8);
    let mut coll = coll;
    let mut speed = speed;
    let mut index: i32 = (coll).ceiling().index();
    top.set_x((coll).ecb().top().x());
    top.set_y((coll).ecb().top().y());
    top.set_z(0.0);
    return fns::mpGetSpeed(ctx, index, top, speed);
}

